/// Builds the resource portability descriptor served through
/// `resource_support_fn` (heap-backed, so it lives behind the `LazyLock`
/// rather than in the `ProviderInfo` static).
fn build_resource_support() -> ProviderCapabilities {
    ProviderCapabilities {
        provider: Provider::Codex,
        skills: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".codex/skills")),
            user_path: Some(PathBuf::from(".codex/skills")),
            also_reads_from: vec![PathBuf::from(".claude/skills"), PathBuf::from(".agents/skills")],
            notes: None,
            properties: Some(ResourcePropertySchema::new(
                &["name", "description"],
                &["license", "compatibility", "metadata"],
                "claudine/docs/cross-referencing/codex.md",
            )),
        },
        commands: ResourceSupport {
            level: SupportLevel::CustomFormat,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from("")),
            user_path: Some(PathBuf::from(".codex/prompts")),
            also_reads_from: vec![],
            notes: Some("Deprecated custom prompts; user scope only; prefer skills"),
            properties: Some(ResourcePropertySchema::new(
                &[],
                &["description", "argument-hint"],
                "claudine/docs/cross-referencing/codex.md",
            )),
        },
        agents: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".codex/agents")),
            user_path: Some(PathBuf::from(".codex/agents")),
            also_reads_from: vec![],
            notes: None,
            properties: None,
        },
        scripts: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Executable),
            repo_path: Some(PathBuf::from(".codex/scripts")),
            user_path: Some(PathBuf::from(".codex/scripts")),
            also_reads_from: vec![],
            notes: None,
            properties: None,
        },
        skill_frontmatter: SkillFrontmatter {
            name: true,
            description: true,
            license: true,
            compatibility: true,
            metadata: true,
            allowed_tools: false,
            user_invocable: false,
            disable_model_invocation: false,
        },
    }
}
